export type Outfit = 'pumpkin' | 'santa' | 'party'
export const OUTFITS: readonly Outfit[] = ['pumpkin', 'santa', 'party']
const HATS: Record<Outfit, { rows: [string, string]; paint: Record<string, number> }> = {
  pumpkin: { rows: ['..PPGP..', '.PDPPDP.'], paint: { P: 0xff8c1a, D: 0xd9480f, G: 0x3fa34d } },
  santa: { rows: ['..RRRRW.', '.WWWWWW.'], paint: { R: 0xe03131, W: 0xffffff } },
  party: { rows: ['...MY...', '..YMYM..'], paint: { M: 0xe879f9, Y: 0xfacc15 } },
}

// The wall clock where the person is: `now` shifted by their UTC offset, read with the UTC getters,
// so it's right whatever time zone the mod's own sandbox runs in.
export const localDate = (now: number, offsetMin: number) => new Date(now + offsetMin * 60_000)

// Dressed for the day: a pumpkin the week before Halloween, a Santa hat over Christmas, a party
// hat for New Year and on the pet's birthday (the day it hatched, from its first year on).
export function outfitFor(now: number, born: number, offsetMin = 0): Outfit | undefined {
  const d = localDate(now, offsetMin)
  const month = d.getUTCMonth() + 1
  const day = d.getUTCDate()
  const b = localDate(born, offsetMin)
  if (born > 0 && d.getUTCFullYear() > b.getUTCFullYear() && month === b.getUTCMonth() + 1 && day === b.getUTCDate()) return 'party'
  if (month === 10 && day >= 25) return 'pumpkin'
  if (month === 12 && day >= 18 && day <= 26) return 'santa'
  if ((month === 12 && day === 31) || (month === 1 && day === 1)) return 'party'
  return undefined
}

// How it's drawn beyond mood and colour: a hat, how worn out a full context makes it (0..1:
// slower, heavier bobbing), and calm, for people who'd rather it barely moved.
export type Style = { outfit?: Outfit | undefined; tired?: number; calm?: boolean }

const BODY = [
  '..oooo..',
  '.obbbbo.',
  'obbbbbbo',
  'obbbbbbo',
  'opbbbbpo',
  '.obbbbo.',
  '.oo..oo.',
]

type Eyes = 'open' | 'glance' | 'closed' | 'happy' | 'dizzy' | 'wide'
type Mouth = 'smile' | 'open' | 'flat' | 'o' | 'gasp'

// Eyes are 1x2 at body columns 2 and 5, rows 2-3: [top, bottom].
const EYES: Record<Eyes, [string, string]> = {
  open: ['w', 'k'],
  glance: ['k', 'k'],
  closed: ['b', 'k'],
  happy: ['k', 'b'],
  dizzy: ['k', 'w'],
  wide: ['k', 'k'],
}
const MOUTHS: Record<Mouth, [x: number, y: number, c: 'k' | 'r'][]> = {
  smile: [[3, 5, 'k'], [4, 5, 'k']],
  open: [[3, 4, 'k'], [4, 4, 'k'], [3, 5, 'r'], [4, 5, 'r']],
  flat: [[2, 5, 'k'], [3, 5, 'k'], [4, 5, 'k'], [5, 5, 'k']],
  o: [],
  gasp: [[3, 4, 'k'], [4, 4, 'k'], [3, 5, 'k'], [4, 5, 'k']],
}

// Rhythm per mood: how fast it bobs (ms per cycle) and whether it shakes instead.
const RHYTHM: Record<Mood, { period: number; shake?: boolean; still?: boolean }> = {
  reading: { period: 1400 },
  wince: { period: 200, shake: true },
  shocked: { period: 300 },
  idle: { period: 2400 },
  working: { period: 640 },
  happy: { period: 480 },
  oops: { period: 260, shake: true },
  calling: { period: 520 },
  sleepy: { period: 3600, still: true },
  dozing: { period: 3000, still: true },
  waking: { period: 520 },
  loved: { period: 900 },
}

const wave = (t: number, period: number) => 0.5 - 0.5 * Math.cos((2 * Math.PI * (t % period)) / period)

// Blink for 140ms every few seconds, at a beat that doesn't look mechanical.
export const isBlinking = (t: number) => (t % 3700) < 140 || ((t + 1300) % 6100) < 120

// look: where the eyes point, -1 left, 0 ahead, 1 right (reading along as you type).
// t: the clock, for extras that drift (a sleeper's z's).
type Pose = { lift?: number; dx?: number; blink?: boolean; odd?: boolean; look?: number; color?: string; t?: number; withBody?: boolean; withExtras?: boolean; outfit?: Outfit | undefined }

// One still frame. The terminal animates by drawing many of these; the desktop SVG layers a few.
export function draw(mood: Mood, { lift = 0, dx = 0, blink = false, odd = false, look = 0, color = DEFAULT_COLOR, t = 0, withBody = true, withExtras = true, outfit }: Pose = {}): Grid {
  const { body, edge } = paletteFor(color)
  const eyes: Eyes =
    mood === 'happy' || mood === 'loved' ? 'happy'
    : mood === 'sleepy' ? 'closed'
    : mood === 'dozing' ? (blink ? 'open' : 'closed') // heavy lids: only now and then do they open
    : mood === 'waking' ? (blink ? 'closed' : 'open') // quick bleary blinks
    : mood === 'oops' ? 'dizzy'
    : mood === 'wince' ? 'closed'
    : mood === 'shocked' ? 'wide'
    : blink ? 'closed'
    : mood === 'working' && odd ? 'glance'
    : 'open'
  const mouth: Mouth = mood === 'happy' || mood === 'calling' ? 'open' : mood === 'oops' || mood === 'wince' ? 'flat' : mood === 'sleepy' ? 'o' : mood === 'shocked' || mood === 'dozing' || mood === 'waking' ? 'gasp' : 'smile'

  const grid: Grid = Array.from({ length: HEIGHT }, () => Array<number | null>(WIDTH).fill(null))
  const ox = 1 + dx
  const oy = 1 - lift
  const put = (x: number, y: number, c: number) => {
    if (x >= 0 && x < WIDTH && y >= 0 && y < HEIGHT) grid[y]![x] = c
  }
  const paint = { o: edge, b: body, p: BLUSH, k: INK, w: WHITE, r: TONGUE } as const

  if (withBody) {
    BODY.forEach((row, y) => [...row].forEach((c, x) => c !== '.' && put(ox + x, oy + y, paint[c as keyof typeof paint])))
    const shift = mood === 'reading' ? Math.max(-1, Math.min(1, Math.round(look))) : 0
    for (const col of [2 + shift, 5 + shift]) EYES[eyes].forEach((c, i) => put(ox + col, oy + 2 + i, paint[c as keyof typeof paint]))
    for (const [x, y, c] of MOUTHS[mouth]) put(ox + x, oy + y, paint[c])
    if (outfit) {
      const hat = HATS[outfit]
      hat.rows.forEach((row, y) => [...row].forEach((c, x) => c !== '.' && put(ox + x, oy + y, hat.paint[c]!)))
    }
  }
  if (withExtras) {
    if (mood === 'happy') for (const [x, y] of odd ? [[0, 1], [9, 3]] : [[9, 0], [0, 4]]) put(x!, y!, SPARK)
    if (mood === 'oops') put(9, 2 + (odd ? 1 : 0), SWEAT)
    if (mood === 'sleepy') {
      // Two z's drifting up and away, half a cycle apart, and a snore bubble on the breath.
      const path = [[7, 4], [8, 3], [8, 2], [9, 1], [9, 0]]
      for (const offset of [0, 2]) {
        const [x, y] = path[(Math.floor(t / 420) + offset) % path.length]!
        put(x!, y!, ZZZ)
      }
      if (Math.floor(t / 1800) % 2 === 0) put(9, 4, SWEAT) // the snore bubble, beside the cheek
    }
    if (mood === 'loved') for (const [x, y] of odd ? [[8, 0], [9, 1]] : [[0, 0], [1, 1]]) put(x!, y!, HEART)
    if (mood === 'shocked') for (const y of [0, 1, 3]) put(9, y, odd ? SPARK : 0xff6b6b) // a blinking "!"
    if (mood === 'wince') put(odd ? 9 : 8, 2, SWEAT)
    if (mood === 'calling') {
      // A "!" beside it and an arm waving: over here!
      for (const y of [0, 1, 3]) put(0, y, ALERT)
      put(9, odd ? 2 : 3, paletteFor(color).edge)
    }
  }
  return grid
}

// The frame at time t: bob or shake on the mood's rhythm, blink now and then, twinkle the extras.
export function sprite(mood: Mood, t: number, look = 0, color = DEFAULT_COLOR, style: Style = {}): Grid {
  const rhythm = RHYTHM[mood]
  const phase = wave(t, periodOf(mood, style.tired))
  const isStill = rhythm.still || style.calm
  const lids = mood === 'dozing' ? (t % 1800) < 420 : mood === 'waking' ? (t % 520) < 140 : isBlinking(t)
  return draw(mood, {
    lift: isStill || rhythm.shake ? 0 : phase > 0.5 ? 1 : 0,
    dx: rhythm.shake && !isStill ? (phase > 0.5 ? 1 : -1) : 0,
    blink: lids,
    odd: Math.floor(t / 350) % 2 === 1,
    look,
    color,
    t,
    outfit: style.outfit,
  })
}

// A full context slows its everyday moods down: at the brim it bobs at about half speed.
const SLOWS: readonly Mood[] = ['idle', 'working', 'reading']
export const periodOf = (mood: Mood, tired = 0) => Math.round(RHYTHM[mood].period * (SLOWS.includes(mood) ? 1 + Math.min(1, Math.max(0, tired)) : 1))

export function mix(a: number, b: number, t: number): number {
  const ch = (shift: number) => Math.round(((a >> shift) & 255) * (1 - t) + ((b >> shift) & 255) * t)
  return (ch(16) << 16) | (ch(8) << 8) | ch(0)
}

// A crossfade between two poses: colors blend, and a pixel that appears or vanishes swaps halfway.
export function blend(from: Grid, to: Grid, t: number): Grid {
  return to.map((row, y) => row.map((c, x) => {
    const a = from[y]?.[x] ?? null
    if (a === null || c === null) return t < 0.5 ? a : c
    return mix(a, c, t)
  }))
}

export type Run = { text: string; fg?: string; bg?: string }
export const hex = (color: number) => `#${color.toString(16).padStart(6, '0')}`

// Two pixels per cell with half blocks; empty pixels draw nothing, so the surface shows through.
export const toRuns = (grid: Grid) => toRunsOf(grid, WIDTH)

export function toRunsOf(grid: Grid, width: number): Run[][] {
  const rows: Run[][] = []
  for (let y = 0; y < grid.length; y += 2) {
    const runs: Run[] = []
    for (let x = 0; x < width; x++) {
      const top = grid[y]![x] ?? null
      const bottom = grid[y + 1]?.[x] ?? null
      const cell: Run =
        top === null && bottom === null ? { text: ' ' }
        : top === null ? { text: '▄', fg: hex(bottom!) }
        : bottom === null ? { text: '▀', fg: hex(top) }
        : top === bottom ? { text: '█', fg: hex(top) }
        : { text: '▀', fg: hex(top), bg: hex(bottom) }
      const last = runs[runs.length - 1]
      if (last && last.fg === cell.fg && last.bg === cell.bg) last.text += cell.text
      else runs.push(cell)
    }
    rows.push(runs)
  }
  return rows
}

// Desktop: one SVG with the motion built in, so it animates without redraws. The body glides on
// an eased curve (smoother than whole pixels), blinks and twinkles switch layers, and a mood change
// fades the previous pose out. Every animated layer rests where a still image should be, so a
// surface that ignores SMIL still shows a clean pet.
export function petSvg(mood: Mood, from?: { mood: Mood; color: string }, look = 0, color = DEFAULT_COLOR, px = 5, style: Style = {}): string {
  const { outfit, calm = false } = style
  // Pixels as rects, a row's same-coloured neighbours merged; with `over`, only the pixels that differ from it.
  const rects = (grid: Grid, over?: Grid) =>
    grid.map((row, y) => {
      const cells = row.map((c, x) => (over && (over[y]![x] ?? null) === c ? null : c))
      let out = ''
      for (let x = 0; x < WIDTH; ) {
        let end = x + 1
        while (end < WIDTH && cells[end] === cells[x]) end++
        if (cells[x] !== null) out += `<rect x="${x * px}" y="${y * px}" width="${(end - x) * px}" height="${px}" fill="${hex(cells[x]!)}"/>`
        x = end
      }
      return out
    }).join('')
  const ease = 'calcMode="spline" keyTimes="0;0.5;1" keySplines="0.45 0 0.55 1;0.45 0 0.55 1"'
  const once = (ms: number, spline = '0.2 0.8 0.2 1') => `dur="${ms}ms" calcMode="spline" keyTimes="0;1" keySplines="${spline}" fill="freeze"`
  const rhythm = RHYTHM[mood]
  // How the body moves: a bob or a shake on the mood's rhythm; asleep, a slow breath that swells it
  // a touch; dozing off, a slow sink; waking, a rise from that sink with a little overshoot.
  const period = periodOf(mood, style.tired)
  const motion =
    calm ? ''
    : mood === 'sleepy' ? `<animateTransform attributeName="transform" type="translate" values="0 0;0 ${-px * 0.35};0 0" dur="3600ms" ${ease} repeatCount="indefinite"/>`
    : mood === 'dozing' ? `<animateTransform attributeName="transform" type="translate" from="0 0" to="0 ${px * 0.6}" ${once(2600, '0.4 0 0.6 1')}/>`
    : mood === 'waking' ? `<animateTransform attributeName="transform" type="translate" values="0 ${px * 0.6};0 ${-px * 0.5};0 0" keyTimes="0;0.6;1" dur="1100ms" calcMode="spline" keySplines="0.2 0.8 0.3 1;0.4 0 0.6 1" fill="freeze"/>`
    : rhythm.shake ? `<animateTransform attributeName="transform" type="translate" values="${-px * 0.6} 0;${px * 0.6} 0;${-px * 0.6} 0" dur="${period}ms" ${ease} repeatCount="indefinite"/>`
    : `<animateTransform attributeName="transform" type="translate" values="0 0;0 ${-px * (mood === 'idle' || mood === 'reading' ? 0.6 : 1)};0 0" dur="${period}ms" ${ease} repeatCount="indefinite"/>`
  const toggle = (dur: number, on: string) => `<animate attributeName="opacity" values="0;1" keyTimes="0;${on}" calcMode="discrete" dur="${dur}ms" repeatCount="indefinite"/>`

  const base = draw(mood, { withExtras: false, look, color, outfit })
  // Lids: a blink now and then; dozing, heavy lids that open less and less; waking, quick bleary blinks.
  const lids =
    mood === 'idle' || mood === 'working' || mood === 'reading' ? `<g opacity="0">${rects(draw(mood, { blink: true, withExtras: false, look, color, outfit }), base)}${toggle(3700, '0.962')}</g>`
    : mood === 'dozing' ? `<g opacity="0">${rects(draw(mood, { blink: true, withExtras: false, color, outfit }), base)}<animate attributeName="opacity" values="0;1;0;1;0" keyTimes="0;0.1;0.35;0.45;1" calcMode="discrete" dur="2600ms" fill="freeze"/></g>`
    : mood === 'waking' ? `<g opacity="0">${rects(draw(mood, { blink: true, withExtras: false, color, outfit }), base)}<animate attributeName="opacity" values="1;0;1;0" keyTimes="0;0.25;0.4;0.6" calcMode="discrete" dur="1100ms" fill="freeze"/></g>`
    : ''
  const glance = mood === 'working' ? `<g opacity="0">${rects(draw(mood, { odd: true, withExtras: false, color, outfit }), base)}${toggle(700, '0.5')}</g>` : ''

  // Asleep: z's that drift up and fade, one after another, and a snore bubble that swells and pops.
  // Calm, they fade in and out where they are.
  const z = (begin: number) =>
    `<g opacity="0"><rect x="${px * (calm ? 7.6 + begin / 1300 : 7.6)}" y="${px * (calm ? 3 - begin / 700 : 3.6)}" width="${px * 0.9}" height="${px * 0.9}" fill="#cfd8ff"/>`
    + (calm ? '' : `<animateTransform attributeName="transform" type="translate" values="0 0;${px * 1.2} ${-px * 3.4}" dur="2400ms" begin="${begin}ms" repeatCount="indefinite"/>`)
    + `<animate attributeName="opacity" values="0;0.95;0" keyTimes="0;0.25;1" dur="2400ms" begin="${begin}ms" repeatCount="indefinite"/></g>`
  const snore = mood === 'sleepy'
    ? z(0) + z(800) + z(1600)
      + `<circle shape-rendering="geometricPrecision" cx="${px * 6.9}" cy="${px * 6.2}" r="0" fill="#7fdbff" fill-opacity="0.55" stroke="#bfefff" stroke-opacity="0.8" stroke-width="0.6"><animate attributeName="r" values="0;${px * 0.9};${px * 1.25};0;0" keyTimes="0;0.55;0.7;0.72;1" dur="3600ms" repeatCount="indefinite"/></circle>`
    : ''
  const extrasA = mood === 'sleepy' ? '' : rects(draw(mood, { withBody: false, color }))
  const extrasB = mood === 'sleepy' ? '' : rects(draw(mood, { withBody: false, odd: true, color }))
  const twinkle = extrasA || extrasB
    ? `<g>${extrasA}<animate attributeName="opacity" values="1;0" keyTimes="0;0.5" calcMode="discrete" dur="700ms" repeatCount="indefinite"/></g><g opacity="0">${extrasB}${toggle(700, '0.5')}</g>`
    : ''
  const fade = from && (from.mood !== mood || from.color !== color)
    ? `<g opacity="0">${rects(draw(from.mood, { color: from.color, outfit }))}<animate attributeName="opacity" values="1;0" dur="350ms" fill="freeze"/></g>`
    : ''
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH * px}" height="${HEIGHT * px}" viewBox="0 0 ${WIDTH * px} ${HEIGHT * px}" shape-rendering="crispEdges"><g>${rects(base)}${lids}${glance}${motion}</g>${twinkle}${snore}${fade}</svg>`
}

files.hooks/status.ts:
// What the pet says while Claude works, one line per kind of action, and the desktop's slide
// between one line and the next.

const base = (path: unknown) => (typeof path === 'string' ? path.split('/').filter(Boolean).pop() ?? path : 'a file')
const clip = (text: unknown, max = 28) => {
  const s = String(text ?? '').replace(/\s+/g, ' ').trim()
  return s.length > max ? `${s.slice(0, max - 1)}…` : s
}

const SHELL: [RegExp, string][] = [
  [/\b(jest|vitest|pytest|mocha|rspec|phpunit|go test|cargo test|(npm|pnpm|yarn|bun) (run )?test)\b/, 'is running the tests 🧪'],
  [/\bgit commit\b/, 'is committing the work ✍️'],
  [/\bgit push\b/, 'is pushing to the remote 🚀'],
  [/\bgit (pull|fetch|clone)\b/, 'is pulling from git…'],
  [/\bgit (diff|status|log|show|blame)\b/, 'is checking the git history…'],
  [/\bgit\b/, 'is talking to git…'],
  [/\b((npm|pnpm|yarn|bun) (i|install|add)|pip3? install|poetry add|cargo add|brew install|go get|gem install)\b/, 'is installing packages 📦'],
  [/\b(tsc|webpack|vite build|next build|make|cargo build|go build|gradle|mvn|(npm|pnpm|yarn|bun) run build)\b/, 'is building the project 🔨'],
  [/\b(eslint|prettier|ruff|black|flake8|rubocop|biome|(npm|pnpm|yarn|bun) run lint)\b/, 'is tidying the code style…'],
  [/\b(docker|kubectl|helm|terraform)\b/, 'is poking the infrastructure 🐳'],
  [/\b(curl|wget|http)\b/, 'is fetching something from the web…'],
  [/^\s*(ls|cat|head|tail|find|tree|pwd|wc)\b/, 'is looking around the repo 👀'],
  [/\b(rm|mv|cp|mkdir)\b/, 'is moving files around…'],
]

// What kind of work a call is, so a run of the same kind (five reads in a row) is told once.
export function actionKind(tool: string, args: Record<string, unknown>): string | undefined {
  if (tool === 'Read' || tool === 'NotebookRead') return 'read'
  if (tool === 'Edit' || tool === 'MultiEdit' || tool === 'Write' || tool === 'NotebookEdit') return 'edit'
  if (tool === 'Grep' || tool === 'Glob' || tool === 'LS') return 'search'
  if (tool === 'WebSearch' || tool === 'WebFetch') return 'web'
  if (tool === 'Bash') {
    const cmd = String(args.command ?? '')
    const at = SHELL.findIndex(([re]) => re.test(cmd))
    return at < 0 ? 'shell' : `shell:${at}`
  }
  const mcp = /^mcp__([^_]+(?:_[^_]+)*)__/.exec(tool)?.[1]
  if (mcp) return `mcp:${mcp}`
  return actionLine(tool, args) === undefined ? undefined : tool
}

const shellRe = (line: string) => SHELL.find(([, l]) => l.startsWith(line))![0]
const TESTS = shellRe('is running the tests')
const BUILD = shellRe('is building')
const count = (text: string, re: RegExp) => Number(re.exec(text)?.[1] ?? 0)

// What came of a call worth reacting to: tests passing or failing, a push landing or bouncing,
// a build breaking. Undefined for everything else, which the pet lets pass without comment.
export function outcomeOf(tool: string, args: Record<string, unknown>, isError: boolean, text = ''): { tone: 'good' | 'bad'; line: string } | undefined {
  if (tool !== 'Bash') return undefined
  const cmd = String(args.command ?? '')
  if (TESTS.test(cmd)) {
    const failed = count(text, /(\d+)\s+(?:tests?\s+)?(?:failed|failing|failures?)\b/i)
    const passed = count(text, /(\d+)\s+(?:tests?\s+)?(?:passed|passing)\b/i)
    if (isError || failed > 0) return { tone: 'bad', line: failed > 0 ? `saw ${failed} test${failed === 1 ? '' : 's'} fail ❌` : 'saw the tests fail ❌' }
    return { tone: 'good', line: passed > 0 ? `cheers: all ${passed} tests pass ✅` : 'cheers: the tests pass ✅' }
  }
  if (/\bgit push\b/.test(cmd)) return isError ? { tone: 'bad', line: 'saw the push bounce 😬' } : { tone: 'good', line: 'watched it ship 🚀' }
  if (isError && BUILD.test(cmd)) return { tone: 'bad', line: 'saw the build break 🔨' }
  return undefined
}

// Once a turn runs long, one quiet summary instead of a line per step.
export const focusLine = (steps: number, files: number) => `is deep in it · ${steps} steps${files ? ` · ${files} file${files === 1 ? '' : 's'} changed` : ''}`

// The line for a tool call that's starting, or undefined for a tool not worth a line.
export function actionLine(tool: string, args: Record<string, unknown>): string | undefined {
  const t = tool
  if (t === 'Read' || t === 'NotebookRead') return `is reading ${base(args.file_path ?? args.notebook_path)}…`
  if (t === 'Edit' || t === 'MultiEdit') return `is editing ${base(args.file_path)} ✏️`
  if (t === 'Write') return `is writing ${base(args.file_path)} ✏️`
  if (t === 'NotebookEdit') return 'is editing a notebook 📓'
  if (t === 'Bash') {
    const cmd = String(args.command ?? '')
    return SHELL.find(([re]) => re.test(cmd))?.[1] ?? `is running \`${clip(cmd.split(/\s+/)[0], 16)}\`…`
  }
  if (t === 'Grep') return `is searching for "${clip(args.pattern, 22)}" 🔍`
  if (t === 'Glob' || t === 'LS') return `is looking for ${clip(args.pattern ?? args.path, 22)}…`
  if (t === 'WebSearch') return `is searching the web for "${clip(args.query, 22)}" 🌐`
  if (t === 'WebFetch') {
    const host = /^https?:\/\/([^/]+)/.exec(String(args.url ?? ''))?.[1]
    return `is reading ${host ?? 'a web page'} 🌐`
  }
  if (t === 'TodoWrite' || t === 'TaskCreate' || t === 'TaskUpdate') return 'is planning the next steps 📝'
  if (t === 'EnterPlanMode' || t === 'ExitPlanMode') return 'is drafting a plan 🗺️'
  if (t === 'AskUserQuestion') return 'has a question for you ❓'
  if (t === 'Skill') return `is using the ${clip(args.skill ?? args.name, 20)} skill 🧰`
  if (t === 'Agent' || t === 'Task') return `is sending a helper off ${args.subagent_type ? `(${clip(args.subagent_type, 16)}) ` : ''}🧭`
  const mcp = /^mcp__([^_]+(?:_[^_]+)*)__/.exec(t)?.[1]
  if (mcp) return `is asking ${clip(mcp.replace(/[-_]/g, ' '), 20)}…`
  return undefined
}

export type LineColors = { name: string; text: string; good: string; bad: string; ask: string }
export const LINE_COLORS: Record<'dark' | 'light', LineColors> = {
  dark: { name: '#d97757', text: '#e6e6e6', good: '#4ade80', bad: '#f87171', ask: '#fbbf24' },
  light: { name: '#c4613f', text: '#1f2328', good: '#15803d', bad: '#b91c1c', ask: '#b45309' },
}
export const toneColor = (colors: LineColors, tone: 'plain' | 'good' | 'bad' | 'ask' = 'plain') => (tone === 'plain' ? colors.text : colors[tone])

const escape = (s: string) => s.replace(/[<>&"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[c]!)

// Desktop: the line as SVG text. The name stays put; only what follows it moves: the new words
// rise from below while the old ones drift up and fade (calm: they just cross-fade). Each status
// carries the name invisibly in front of it, so it starts exactly where the name ends in any font.
// Each layer rests where a still image should be, so without SMIL only the new line shows.
export const lineWidth = (name: string, line: string, previous?: string) => Math.min(640, Math.ceil((name.length + 1 + Math.max(line.length, previous?.length ?? 0)) * 7.9) + 24)

export function lineSvg(name: string, line: string, previous: string | undefined, colors: LineColors, { tone = 'plain', calm = false }: { tone?: 'plain' | 'good' | 'bad' | 'ask'; calm?: boolean } = {}): string {
  const width = lineWidth(name, line, previous)
  const status = (l: string, fill: string) => `<tspan font-weight="700" fill-opacity="0">${escape(name)}</tspan><tspan fill="${fill}"> ${escape(l)}</tspan>`
  const ease = 'dur="0.38s" calcMode="spline" keyTimes="0;1" keySplines="0.2 0.8 0.2 1" fill="freeze"'
  const isChange = previous !== undefined && previous !== line
  const old = isChange
    ? `<text x="0" y="${calm ? 15 : -4}" opacity="0">${status(previous, colors.text)}${calm ? '' : `<animate attributeName="y" values="15;-4" ${ease}/>`}<animate attributeName="opacity" values="1;0" ${ease}/></text>`
    : ''
  const rise = isChange ? `${calm ? '' : `<animate attributeName="y" values="32;15" ${ease}/>`}<animate attributeName="opacity" values="0;1" ${ease}/>` : ''
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="20" viewBox="0 0 ${width} 20" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, system-ui, sans-serif" font-size="14">`
    + `${old}<text x="0" y="15">${status(line, toneColor(colors, tone))}${rise}</text>`
    + `<text x="0" y="15" fill="${colors.name}" font-weight="700">${escape(name)}</text></svg>`
}

