// The pet's little helpers, one per running subagent: half its size (5x4 body, plus a column for a
// waving arm), in the agent's own colour. They pop in, bob while their agent works, and when it's
// done they wave bye, float up and fade away.
import type { Grid } from './sprite'
import { COLOR_NAMES, hex, paletteFor } from './sprite'

export const MINI_W = 6
export const MINI_H = 4
export const ARRIVE_MS = 600
export const WAVE_MS = 1300
export const LEAVE_MS = 2200

const INK = 0x1a1a2e
const BODY = ['.ooo.', 'okbko', 'obbbo', '.o.o.']

// A stable colour for an agent with none of its own, never the parent's.
export function miniColor(id: string, avoid: string): string {
  const names = COLOR_NAMES.filter(name => name !== avoid && name !== 'black' && name !== 'white')
  let h = 0
  for (const ch of id) h = (h * 31 + ch.charCodeAt(0)) >>> 0
  return names[h % names.length]!
}

// The Claude Code agent colours as a definition file names them, onto the pet's palette.
const AGENT_COLORS: Record<string, string> = { red: 'red', blue: 'blue', green: 'green', yellow: 'yellow', purple: 'purple', orange: 'orange', pink: 'pink', cyan: 'cyan' }
export const colorFromDefinition = (markdown: string) => {
  const front = /^---\n([\s\S]*?)\n---/.exec(markdown)?.[1] ?? ''
  const named = /^color:\s*["']?([a-z]+)/im.exec(front)?.[1]?.toLowerCase()
  return named ? AGENT_COLORS[named] ?? (COLOR_NAMES.includes(named) ? named : undefined) : undefined
}

export function miniDraw(color: string, { blink = false, armUp = false, arm = false } = {}): Grid {
  const { body, edge } = paletteFor(color)
  const paint: Record<string, number> = { o: edge, b: body, k: blink ? body : INK }
  const grid: Grid = BODY.map(row => [...row].map(c => (c === '.' ? null : paint[c]!)))
  for (const row of grid) row.push(null)
  if (arm) grid[armUp ? 0 : 1]![5] = edge
  return grid
}

// Terminal frames, by how long the mini has been in its state.
export function miniFrame(color: string, state: 'here' | 'bye', age: number, seed: number): Grid | null {
  if (state === 'here' && age < ARRIVE_MS) {
    // A sparkle, then the body: a pop in two beats.
    if (age < 200) return Array.from({ length: MINI_H }, (_, y) => Array.from({ length: MINI_W }, (_, x) => (x === 2 && y === 1 ? 0xffe066 : null)))
    return miniDraw(color)
  }
  if (state === 'bye') {
    if (age < WAVE_MS) return miniDraw(color, { arm: true, armUp: Math.floor(age / 220) % 2 === 0 })
    if (age < WAVE_MS + 300) return miniDraw(color, { blink: true })
    if (age < WAVE_MS + 550) return Array.from({ length: MINI_H }, (_, y) => Array.from({ length: MINI_W }, (_, x) => (x === 2 && y === 1 ? 0xcfd8ff : null)))
    return null
  }
  return miniDraw(color, { blink: (age + seed * 377) % 3100 < 130 })
}

export const seedOf = (id: string) => [...id].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) >>> 0, 7) % 997

// Desktop: one helper drawn at its slot's origin, its story told by its age: once its slot has
// opened (SLOT_MS) it pops in with a little spring, then bobs and blinks at its own pace; leaving,
// it waves, floats up and fades. Laid out by the band's second line (line2.ts).
export const SLOT_MS = 380

export function miniBody(mini: { id: string; color: string; state: 'here' | 'bye'; age: number }, px = 5, calm = false): string {
  const w = MINI_W * px
  const h = MINI_H * px
  const rects = (grid: Grid) => grid.map((row, y) => row.map((c, x) => (c === null ? '' : `<rect x="${x * px}" y="${y * px}" width="${px}" height="${px}" fill="${hex(c)}"/>`)).join('')).join('')
  const seed = seedOf(mini.id)
  if (mini.state === 'bye') {
    const wave = (up: boolean) => `<g opacity="${up ? 1 : 0}">${rects(miniDraw(mini.color, { arm: true, armUp: up }))}<animate attributeName="opacity" values="${up ? '1;0' : '0;1'}" keyTimes="0;0.5" calcMode="discrete" dur="440ms" repeatCount="${Math.ceil(WAVE_MS / 440)}" fill="freeze"/></g>`
    const fadeAt = Math.max(0, WAVE_MS - mini.age)
    return `<g>${wave(true)}${wave(false)}`
      + `<animateTransform attributeName="transform" type="translate" values="0 0;0 ${-px * 1.6}" dur="800ms" begin="${fadeAt}ms" calcMode="spline" keyTimes="0;1" keySplines="0.3 0 0.7 1" fill="freeze"/>`
      + `<animate attributeName="opacity" values="1;0" dur="800ms" begin="${fadeAt}ms" fill="freeze"/></g>`
  }
  const spline = 'calcMode="spline" keySplines="0.45 0 0.55 1;0.45 0 0.55 1"'
  const bob = `<animateTransform attributeName="transform" type="translate" values="0 0;0 ${-px * 0.7};0 0" keyTimes="0;0.5;1" dur="${560 + (seed % 240)}ms" ${spline} repeatCount="indefinite"/>`
  const blink = `<g opacity="0">${rects(miniDraw(mini.color, { blink: true }))}<animate attributeName="opacity" values="0;1" keyTimes="0;0.96" calcMode="discrete" dur="${2900 + (seed % 900)}ms" begin="${-(seed % 2900)}ms" repeatCount="indefinite"/></g>`
  const body = `<g>${rects(miniDraw(mini.color))}${blink}${calm ? '' : bob}</g>`
  if (mini.age >= SLOT_MS + ARRIVE_MS) return body
  // Not yet popped: hold at nothing while the slot opens, then spring out from the middle.
  const wait = Math.max(0, SLOT_MS - mini.age)
  const cx = (w - px) / 2
  const cy = h / 2
  return `<g transform="translate(${cx} ${cy})"><g transform="scale(${wait > 0 ? 0 : 1})">`
    + `<animateTransform attributeName="transform" type="scale" values="0;1.2;1" keyTimes="0;0.65;1" dur="${ARRIVE_MS}ms" begin="${wait}ms" calcMode="spline" keySplines="0.2 0.8 0.3 1;0.4 0 0.6 1" fill="freeze"/>`
    + `<g transform="translate(${-cx} ${-cy})">${body}</g></g></g>`
}

files.hooks/line2.ts:
// Desktop: the band's second line as one SVG: the helpers on the left, newest first, then the
// context bar, its percent, the usage windows, the bill and the ⓘ. Each element starts where the
// previous draw left it and glides to its new place, so a helper's slot opening pushes the line
// right and one closing pulls it back.
import { FONT, gradientAt, hex, limitsParts, meterParts } from './meter'
import type { Limit, Tones } from './meter'
import { MINI_W, miniBody } from './mini'

export type Layout = Map<string, number>
export type LineTwo = {
  minis: { id: string; color: string; state: 'here' | 'bye'; age: number }[]
  percent?: number
  from: number
  isWorking: boolean
  limits: Limit[]
  resets?: string
  bill?: string
  hasInfo: boolean
  tones: Tones & { text: string }
  // Calm: the helpers stand still instead of bobbing.
  calm?: boolean
}

const PX = 5
const SLOT = MINI_W * PX + 4
const HEIGHT = 26
const PILL = 110
const GLIDE = 'dur="420ms" calcMode="spline" keyTimes="0;1" keySplines="0.25 0.8 0.25 1" fill="freeze"'

export function lineTwoSvg(line: LineTwo, previous: Layout | undefined): { svg: string; width: number; layout: Layout } {
  const layout: Layout = new Map()
  const minis = line.minis.filter(m => m.age >= 0)
  minis.forEach((m, i) => layout.set(m.id, i * SLOT))
  const contentX = minis.length ? minis.length * SLOT + 4 : 0
  layout.set('content', contentX)

  // Where an element was on the last draw, to glide from; a new helper has no past and pops in.
  const place = (key: string, y: number) => {
    const x = layout.get(key)!
    const was = previous?.get(key)
    const move = was !== undefined && Math.abs(was - x) > 0.5
      ? `<animateTransform attributeName="transform" type="translate" values="${was} ${y};${x} ${y}" ${GLIDE}/>`
      : ''
    return { open: `<g transform="translate(${x} ${y})">${move}`, close: '</g>' }
  }

  let defs = ''
  let content = ''
  let x = 0
  if (line.percent === undefined) {
    content = `<text x="0" y="17.5" fill="${line.tones.label}">context · updates on the next reply</text>`
    x = 230
  } else {
    const meter = meterParts(line.percent, line.from, line.isWorking, PILL)
    defs = meter.defs
    const pct = `${line.percent}%`
    content = `<g transform="translate(3 7)">${meter.body}</g>`
      + `<text x="${PILL + 12}" y="17.5" fill="${hex(gradientAt(line.percent / 100))}" font-weight="700">${pct}</text>`
    x = PILL + 12 + pct.length * 8.4 + 12
    if (line.limits.length) {
      const limits = limitsParts(line.limits, line.tones)
      content += `<g transform="translate(${x.toFixed(1)} 5)">${limits.body}</g>`
      x += limits.width + 10
    }
    if (line.resets) {
      content += `<text x="${x.toFixed(1)}" y="17.5" fill="${line.tones.label}">${line.resets}</text>`
      x += line.resets.length * 7.1 + 10
    }
    if (line.bill) {
      content += `<text x="${x.toFixed(1)}" y="17.5" fill="${line.tones.text}" font-weight="700">${line.bill}</text>`
      x += line.bill.length * 8.4 + 10
    }
  }
  if (line.hasInfo) {
    content += `<text x="${x.toFixed(1)}" y="17.5" fill="${line.tones.label}">ⓘ</text>`
    x += 14
  }

  const helpers = minis.map(m => {
    const at = place(m.id, 5)
    return `${at.open}${miniBody(m, PX, line.calm)}${at.close}`
  })
  const body = place('content', 0)
  const width = Math.ceil(Math.max(contentX + x, (previous?.get('content') ?? 0) + x))
  return {
    layout,
    width,
    svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${HEIGHT}" viewBox="0 0 ${width} ${HEIGHT}" ${FONT}><defs>${defs}</defs>`
      + `<g shape-rendering="crispEdges">${helpers.join('')}</g>${body.open}${content}${body.close}</svg>`,
  }
}

